// ---- Map values into globals (must be set BEFORE ReqAgent) ----
// Customer NUMBER: 'Get Custom Fields' puts the contact custom fields into 'ContactCustomFields'.
//   'customer_id' sits at .contactCustomFields[1] (ident=customer_id). The index is POSITIONAL -
//   re-check it in a trace if you add more contact custom fields.
ASSIGN global:customer_id = "{ContactCustomFields.contactCustomFields[1].value}"
// Customer NAME: the pre-chat name is the system var __authorfullname. CXone locks this at chat
// start and it can never change, which is exactly why it is the identity anchor.
ASSIGN global:customer_nickname = "{__authorfullname}"
ASSIGN dbg_customer_id = "{global:customer_id}"
ASSIGN dbg_nickname    = "{global:customer_nickname}"

IF "{global:customer_id}" = ""
{
  ASSIGN dbg_ic_status = "SKIPPED - no customer_id custom field on this contact"
}
ELSE
{
  // ---- Interaction Context payload ----------------------------------------------------
  // Verified live 2026-08-06: timestamp is REQUIRED (presence, not freshness); contactNumber
  // may be a string; tenantId is OPTIONAL (resolved from the bearer) so it is not sent.
  // contextData stays NESTED - its keys surface as input.data['copilot-customer-context'].*
  DYNAMIC params
  ASSIGN params.schemaVersion = "1.0.0"
  // real timestamp via documented SNL builtins (now is BU-local; asutc() converts to Zulu);
  // the hardcoded fallback guards an EMPTY interpolation result (API checks presence only).
  ASSIGN nowTime = now
  ASSIGN utcTime = nowTime.asutc()
  ASSIGN params.timestamp = "{utcTime.asisodatetime()}"
  IF "{params.timestamp}" = ""
  {
    ASSIGN params.timestamp = "2026-08-06T18:00:00Z"
  }
  ASSIGN params.contactNumber = "{contactid}"
  ASSIGN params.contextData.customer_id = "{global:customer_id}"
  ASSIGN params.contextData.customer_nickname = "{global:customer_nickname}"
  ASSIGN paramsjson = "{params.asjson()}"

  // ---- Bearer token from Connect Auth --------------------------------------------------
  // NO CREDENTIALS IN THIS SCRIPT: Connect Auth mints the token from the Integration Hub
  // connection. authBody wraps the auth response one level deep - the confirmed path is
  // authBody.responseContent.access_token (source: Medallia Mindful x CXone integration
  // guide, the one public production ConnectAuth script). Fallback probes cover tenant /
  // version drift; dbg_tok_path records which path actually served the request.
  ASSIGN tok = "{authBody.responseContent.access_token}"
  ASSIGN dbg_tok_path = "authBody.responseContent.access_token"
  IF "{tok}" = ""
  {
    ASSIGN tok = "{authBody.access_token}"
    ASSIGN dbg_tok_path = "authBody.access_token (fallback)"
  }
  IF "{tok}" = ""
  {
    ASSIGN tok = "{authBody.ResponseContent.access_token}"
    ASSIGN dbg_tok_path = "authBody.ResponseContent.access_token (fallback)"
  }
  IF "{tok}" = ""
  {
    ASSIGN dbg_tok_path = "NONE - expand authBody in the LIVE trace variables panel and report the member names"
  }

  // ---- Publish -------------------------------------------------------------------------
  // pre-seeded so a faulted MakeRestRequest still leaves a marker in the trace
  ASSIGN dbg_ic_status = "REQUEST SENT - no status returned"
  requestProxy = GetRESTProxy()
  ASSIGN requestAuth = "Bearer "
  requestAuth.append("{tok}")
  requestProxy.AddHeader("Authorization", requestAuth)
  requestProxy.ContentType = "application/json"
  customEndpointURL = "https://api-na1.niceincontact.com/eai-real-time-insight/v1/interaction-context"
  customRequest = requestProxy.MakeRestRequest(customEndpointURL, paramsjson, 0, "POST")
  // a REAL status code in the trace - silent success is what hid the ConnectRequest failure
  ASSIGN dbg_ic_status = requestProxy.statusCode

  // scrub token material so an exported trace can be shared safely
  ASSIGN tok = "(scrubbed)"
  ASSIGN requestAuth = "(scrubbed)"
  ASSIGN authBody = "(scrubbed)"
}
